mapper.select:
SELECT 

		ISNULL(MIN(WO.납기일자), #{searchDtFrom}) AS W_MAX_DATE


		ISNULL(MIN(WO.접수일자), #{searchDtFrom}) AS W_MAX_DATE





		 AND WO.납기일자 >= #{listStartDt} 


		 AND WO.접수일자 >= #{listStartDt}

mapper.sql:
WHERE 1=1 AND WO.접수확인 = 'N' AND WO.접수삭제 = 'N' AND (UPC.거래정지일자 = '00000000' OR UPC.거래정지일자 >=CONVERT(VARCHAR,GETDATE(),112) ) AND IC.폐기일자 <= CONVERT(VARCHAR,GETDATE(),112)
AND WO.등록구분 = 'M'
AND WO.등록구분 = 'C'
AND ( UPPER(RTRIM(BPLC.사업장명칭)) LIKE UPPER('%'+ RTRIM(#{searchBplcNm}) +'%') OR UPPER(RTRIM(BPLC.사업장)) LIKE UPPER('%'+ RTRIM(#{searchBplcNm}) +'%') )
AND WO.단가사업장 = #{searchBplcCode}
AND( ( SELECT UPPER(RTRIM(CM2.상호)) FROM 거래처MASTER CM2 WHERE RTRIM(CM2.거래처코드) = WO.거래처코드 AND CM2.등록사업장 = WO.단가사업장) LIKE UPPER('%'+ RTRIM(#{searchBcncNm}) +'%')
OR
( SELECT UPPER(RTRIM(CM2.거래처코드)) FROM 거래처MASTER CM2 WHERE RTRIM(CM2.거래처코드) = WO.거래처코드 AND CM2.등록사업장 = WO.단가사업장) LIKE UPPER('%'+ RTRIM(#{searchBcncNm}) +'%') )
AND WO.거래처코드 = #{searchBcncCode}
AND ( ( SELECT UPPER(RTRIM(CM2.상호)) FROM 거래처MASTER CM2 WHERE CM2.거래처코드 = WO.착지업체 AND CM2.등록사업장 = WO.단가사업장) LIKE UPPER('%'+ RTRIM(#{searchEntrpsNm}) +'%') OR
( SELECT UPPER(RTRIM(CM2.거래처코드)) FROM 거래처MASTER CM2 WHERE CM2.거래처코드 = WO.착지업체 AND CM2.등록사업장 = WO.단가사업장) LIKE UPPER('%'+ RTRIM(#{searchEntrpsNm}) +'%')
)
AND WO.착지업체 = #{searchDlvyEntrps}
AND ( UPPER(RTRIM(IC.품목명)) LIKE UPPER('%'+ RTRIM(#{searchItemNm}) +'%') OR UPPER(RTRIM(IC.품목코드)) LIKE UPPER('%'+ RTRIM(#{searchItemNm}) +'%') )
AND WO.납기일자 >= #{searchDtFrom}
AND WO.납기일자 <= #{searchDtTo}
AND WO.접수일자 >= #{searchDtFrom}
AND WO.접수일자 <= #{searchDtTo}

update.foreach:
UPDATE 웹주문접수 SET
	납기일자 = #{item.wDedt} 
	, 수량 = #{item.wQuantity}
	, 그룹수량 = #{item.wGrpQy}
	, 낱개수량 = #{item.wPieceQy}
	, 단가 = #{item.wUntpc}
	, 주문비고 = #{item.wNote}
	, 중량 = #{item.wWt}
	, 공급가액 = #{item.wSplpCam}
	, 부가세 = #{item.WVat}
	, 합계금액 = #{item.wSumAmount}

		, 진행유무 = #{item.wProgrsse}
		, 관리자비고 = #{item.wAdminNote}

	, 수정자 = #{bcncCode}
	, 수정일자 = CONVERT(VARCHAR,GETDATE(),112)
	, 수정시간 = REPLACE(CONVERT(VARCHAR,GETDATE(),108),':','')
WHERE 접수일자 = #{item.wRceptde}
	AND 일련번호 = #{item.wSn}

UPDATE 웹주문접수 SET
	접수삭제 = 'Y'
	, 수정자 = #{bcncCode}
	, 수정일자 = CONVERT(VARCHAR,GETDATE(),112)
	, 수정시간 = REPLACE(CONVERT(VARCHAR,GETDATE(),108),':','')
WHERE 접수일자 = #{item.wRceptde}
	AND 일련번호 = #{item.wSn}
